<script setup lang="ts">
import ResourceRecovery from './ResourceRecovery.vue';
import {resourceApi} from '#/api/creative-video/resources';
import {studioStorage} from '#/api/creative-video/storage';
import {computed,ref} from 'vue';
import {ElButton,ElInput,ElTag,ElMessage} from 'element-plus';
import {angleLibrary,creativeConcepts,saveCreative,regenerateCreative,favoriteCreative} from '#/api/creative-video/creative';
const props=defineProps<{projectId:number;selected:number}>();const emit=defineEmits<{select:[number]}>();const saved=JSON.parse(studioStorage.getItem(`vidcraft-creative-${props.projectId}`)||'{}') as {note?:string;locked?:boolean};const version=ref(Number(studioStorage.getItem(`vidcraft-creative-batch-${props.projectId}`)||1));const compare=ref<number[]>([]);const syncing=ref(false);const syncStatus=ref('本地方案');const favorites=ref(JSON.parse(studioStorage.getItem(`vidcraft-creative-favorites-${props.projectId}`)||'[]') as {title:string;batch:number}[]);const note=ref(saved.note||'');const locked=ref(saved.locked||false);const concepts=computed(()=>{void version.value;return creativeConcepts(props.projectId);});
function select(index:number){emit('select',index);locked.value=false;saveCreative(props.projectId,index,note.value,false);}
function regenerate(){version.value=regenerateCreative(props.projectId);locked.value=false;note.value='';compare.value=[];emit('select',0);}
function favorite(index:number){favoriteCreative(props.projectId,index);favorites.value=JSON.parse(studioStorage.getItem(`vidcraft-creative-favorites-${props.projectId}`)||'[]');ElMessage.success('方案快照已收藏');}
async function lock(){if(syncing.value)return;syncing.value=true;studioStorage.setItem(`vidcraft-creative-dirty-${props.projectId}`,'true');try{saveCreative(props.projectId,props.selected,note.value,false);const payload=JSON.parse(studioStorage.getItem(`vidcraft-creative-${props.projectId}`)||'{}') as Record<string,unknown>;payload.understandingServerRevision=Number(studioStorage.getItem(`vidcraft-resource-revision-${props.projectId}-understanding`)||0);syncStatus.value='正在保存与校验创意';const result=await resourceApi.save(props.projectId,'creative',payload,true);if(note.value!==payload.note||props.selected!==payload.index){syncStatus.value='方案在保存期间已变化，请重新锁定';return;}saveCreative(props.projectId,props.selected,note.value,true);locked.value=true;studioStorage.removeItem(`vidcraft-creative-dirty-${props.projectId}`);syncStatus.value=`服务端创意 R${result.revision} 已锁定`;}catch{locked.value=false;saveCreative(props.projectId,props.selected,note.value,false);syncStatus.value='锁定失败：请确认产品理解已同步且未过期，或处理版本冲突';ElMessage.warning(syncStatus.value);}finally{syncing.value=false;}}
</script>
<template><section><ResourceRecovery :project-id="projectId" kind="creative"/><p role="status">{{ syncStatus }}</p><details><summary>10类传播切口库</summary><ElTag v-for="a in angleLibrary" :key="a" style="margin:6px">{{ a }}</ElTag></details><p>Mock 方案批次 {{ version }} · 方案依据当前产品理解，仍需核对真实性。</p><ElButton @click="regenerate">再来三套（规则模拟）</ElButton><article v-for="c in concepts" :key="c.id" :class="{selected:selected===c.id}"><h3>{{ c.title }}</h3><ElTag>{{ c.angle }}</ElTag><p>受众：{{ c.audience }}</p><p>场景：{{ c.scene }}</p><p>开头3秒：{{ c.hook }}</p><p>冲突：{{ c.conflict }} → 反转：{{ c.reversal }}</p><p>推荐理由：{{ c.reason }}</p><p>产品出现：{{ c.productMoment }} · CTA：{{ c.cta }}</p><p>风格：{{ c.style }} · 素材成本：{{ c.cost }}（估算）</p><p>证据：{{ c.evidence }}</p><p>风险：{{ c.risk }}</p><p>启发式评估：{{ c.assessment }}（非效果保证）</p><label><input v-model="compare" type="checkbox" :value="c.id"/>加入对比</label><ElButton @click="favorite(c.id)">收藏方案快照</ElButton><ElButton @click="select(c.id)">{{ selected===c.id?'已选择此方案':'选择方案' }}</ElButton></article><div class="comparison" v-if="compare.length>=2"><article v-for="c in concepts.filter(c=>compare.includes(c.id))" :key="c.id"><h3>{{ c.title }}</h3><p>{{ c.scene }}</p><p>{{ c.conflict }}</p><p>{{ c.style }} · {{ c.cost }}</p></article></div><details><summary>收藏的方案（{{ favorites.length }}）</summary><p v-for="(f,i) in favorites" :key="i">批次 {{ f.batch }} · {{ f.title }}</p></details><ElInput @input="locked=false;saveCreative(projectId,selected,note,false)" v-model="note" type="textarea" placeholder="微调要求、禁止表述或补充素材要求"/><ElButton :loading="syncing" :disabled="syncing" @click="lock">{{ locked?'已锁定方向':'保存并锁定方向' }}</ElButton><p>方案在两组预置叙事模板间切换，不代表真实模型生成；收藏保存当时方案快照。</p></section></template>
<style scoped>.comparison{display:grid;grid-template-columns:repeat(2,1fr);gap:12px}article{padding:22px;border:1px solid var(--el-border-color);border-radius:12px;margin:18px 0}.selected{border-color:var(--el-color-primary)}h3{font-size:20px;font-weight:600;margin-bottom:14px}p{line-height:1.8;color:var(--el-text-color-secondary);margin:12px 0}</style>
